import * as THREE from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {createMouse} from './mouse-model.js';
export class MouseViewer{
 constructor(host){
  this.host=host;this.scene=new THREE.Scene();this.scene.background=new THREE.Color('#e8e9e4');
  this.camera=new THREE.PerspectiveCamera(34,1,.001,10);this.camera.position.set(-.14,.15,-.17);
  this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.renderer.setSize(1,1,false);this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=THREE.PCFSoftShadowMap;this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.3;
  const canvas=this.renderer.domElement;canvas.style.width='100%';canvas.style.height='100%';canvas.tabIndex=0;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Interactive 3D mouse. Drag or use arrow keys to rotate; plus and minus to zoom.');host.append(canvas);
  this.controls=new OrbitControls(this.camera,canvas);this.controls.target.set(0,.017,0);this.controls.enablePan=false;this.controls.minDistance=.10;this.controls.maxDistance=.5;this.controls.maxPolarAngle=Math.PI*.94;this.controls.addEventListener('change',()=>this.render());this.controls.update();
  this.scene.add(new THREE.HemisphereLight('#ffffff','#a5a79e',2.5));
  for(const [x,y,z,power] of [[.12,.22,-.06,3],[-.16,.12,.1,1.5]]){const l=new THREE.DirectionalLight('#ffffff',power);l.position.set(x,y,z);if(x>0){l.castShadow=true;l.shadow.mapSize.set(2048,2048);Object.assign(l.shadow.camera,{left:-.12,right:.12,top:.12,bottom:-.12,near:.01,far:1});l.shadow.bias=-.00015;}this.scene.add(l);}
  this.floor=new THREE.Mesh(new THREE.PlaneGeometry(2,2),new THREE.ShadowMaterial({opacity:.15}));this.floor.rotation.x=-Math.PI/2;this.floor.position.y=-.001;this.floor.receiveShadow=true;this.scene.add(this.floor);
  canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key)){e.preventDefault();if(e.key==='+'||e.key==='=')this.zoom(.85);else if(e.key==='-')this.zoom(1.17);else{const v=this.camera.position.clone().sub(this.controls.target);const s=new THREE.Spherical().setFromVector3(v);if(e.key==='ArrowLeft')s.theta-=.15;if(e.key==='ArrowRight')s.theta+=.15;if(e.key==='ArrowUp')s.phi=Math.max(.08,s.phi-.15);if(e.key==='ArrowDown')s.phi=Math.min(3,s.phi+.15);this.camera.position.copy(this.controls.target).add(v.setFromSpherical(s));this.controls.update();}}});
  canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();document.querySelector('[data-mouse-view="photo"]').click();document.querySelector('#mouse-view-status').textContent='3D paused. Select 3D view to try again, or use product photos.';});
  new ResizeObserver(()=>this.resize()).observe(host);
 }
 setColor(slug){if(this.slug===slug)return;this.slug=slug;if(this.model){this.scene.remove(this.model);const materials=new Set();this.model.traverse(o=>{o.geometry?.dispose();if(o.material)materials.add(o.material);});materials.forEach(m=>m.dispose());}this.model=createMouse(slug);this.scene.add(this.model);const bounds=new THREE.Box3().setFromObject(this.model);this.modelRadius=bounds.getBoundingSphere(new THREE.Sphere()).radius;this.controls.target.copy(bounds.getCenter(new THREE.Vector3()));this.resize();}
 render(){this.renderer.render(this.scene,this.camera);}
 // The drawing buffer and camera must use the visible canvas dimensions.
 // Preserve orbit direction and relative zoom when the layout/orientation changes.
 resize(){const w=this.host.clientWidth,h=this.host.clientHeight;if(!w||!h)return;const offset=this.camera.position.clone().sub(this.controls.target);const zoomRatio=this.fitDistance?offset.length()/this.fitDistance:1;this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();const vertical=THREE.MathUtils.degToRad(this.camera.fov)/2;const horizontal=Math.atan(Math.tan(vertical)*this.camera.aspect);this.fitDistance=(this.modelRadius||.07)/Math.sin(Math.min(vertical,horizontal))*1.12;this.controls.minDistance=this.fitDistance*.45;this.controls.maxDistance=this.fitDistance*3;offset.setLength(THREE.MathUtils.clamp(zoomRatio,.45,3)*this.fitDistance);this.camera.position.copy(this.controls.target).add(offset);this.controls.update();this.render();}
 zoom(factor){const v=this.camera.position.clone().sub(this.controls.target);v.setLength(THREE.MathUtils.clamp(v.length()*factor,this.controls.minDistance,this.controls.maxDistance));this.camera.position.copy(this.controls.target).add(v);this.controls.update();this.render();}
 view(name){const directions={angle:[-.14,.13,-.17],top:[0,1,.0001],side:[-1,.18,.01],bottom:[0,-1,.0001]};this.floor.visible=name!=='bottom';const offset=new THREE.Vector3().fromArray(directions[name]||directions.angle).setLength(this.fitDistance||.3);this.camera.position.copy(this.controls.target).add(offset);this.controls.update();this.render();}
}
